window.DockGroupMeMentionState={get:()=>({group:mode==='groups'&&current?.can_post!==false?current?.id:null,entries:mentionEntries,members:groups.find(g=>g.id===(current?.parent_id||current?.id))?.members||[]}),set:entries=>{mentionEntries=entries}};

function mediaReady(row,conversation){if(row.isConnected===false||current?.id!==conversation||messageQuery)return;if(!followingLatest){const position=savedReadingPosition;if(position?.chat===mode+':'+current?.id&&Math.abs(($('messages').scrollTop||0)-position.top)<2)restoreReadingPosition(position);return}const follow=()=>{if(row.isConnected===false||!followingLatest||messageQuery||current?.id!==conversation)return;$('messages').scrollTop=$('messages').scrollHeight;resetNewMessages();markRead()};if(window.requestAnimationFrame)window.requestAnimationFrame(follow);else follow()}

let resolveDeletion=null;
function confirmMessageDeletion(message){if(resolveDeletion)return Promise.resolve(false);$('delete-preview').textContent=(message.text||'[Attachment]').slice(0,280);return new Promise(resolve=>{resolveDeletion=resolve;$('delete-dialog').showModal();$('delete-cancel').focus()})}
function finishDeletion(accepted){const resolve=resolveDeletion;resolveDeletion=null;$('delete-dialog').close();resolve?.(accepted)}
$('delete-cancel').onclick=()=>finishDeletion(false);$('delete-confirm').onclick=()=>finishDeletion(true);$('delete-dialog').oncancel=event=>{event.preventDefault();finishDeletion(false)};$('delete-dialog').onclose=()=>{if(resolveDeletion){const resolve=resolveDeletion;resolveDeletion=null;resolve(false)}};

// A mobile menu closes before opening settings; restore to its visible trigger.
function restoreDialogFocus(){const active=document.activeElement;if(active&&active!==document.body&&active.getClientRects?.().length&&!active.closest?.('dialog'))return;const mobile=window.matchMedia?.('(max-width:650px)').matches,conversation=$('chat-app').dataset.panel==='conversation';const target=mobile&&conversation?$('chat-tools'):$('display-settings');if(target.getClientRects?.().length)target.focus({preventScroll:true})}
for(const id of ['display-dialog','reaction-dialog','notifications-dialog','voice-dialog'])$(id).onclose=restoreDialogFocus;

// Anchor the first visible message when content above it changes height.
function captureReadingPosition(){const root=$('messages'),top=root.scrollTop||0,chat=mode+':'+current?.id;if(!root.getBoundingClientRect)return {top,chat};const edge=root.getBoundingClientRect().top;const anchor=Array.from(root.querySelectorAll('.message')).find(row=>row.getBoundingClientRect().bottom>edge);return {top,chat,id:anchor?.dataset.messageId,offset:anchor?anchor.getBoundingClientRect().top-edge:0}}
function restoreReadingPosition(position,fallback=position.top){const root=$('messages');const anchor=position.id&&Array.from(root.querySelectorAll?.('.message')||[]).find(row=>row.dataset.messageId===position.id);if(anchor?.getBoundingClientRect&&root.getBoundingClientRect)root.scrollTop=(root.scrollTop||0)+anchor.getBoundingClientRect().top-root.getBoundingClientRect().top-position.offset;else root.scrollTop=fallback}
function readingInteractionActive(){if(document.querySelector?.('dialog[open]'))return true;const root=$('messages'),selection=window.getSelection?.();return !!(selection&&!selection.isCollapsed&&(root.contains?.(selection.anchorNode)||root.contains?.(selection.focusNode))||document.activeElement&&root.contains?.(document.activeElement)&&document.activeElement!==root)}

function redrawPreservingPosition(){const position=captureReadingPosition(),follow=nearLatest();renderMessages();if(follow)$('messages').scrollTop=$('messages').scrollHeight;else restoreReadingPosition(position)}

$('image-close').onclick=()=>$('image-dialog').close();$('image-dialog').onclick=event=>{if(event.target===$('image-dialog'))$('image-dialog').close()};$('image-dialog').onclose=()=>{$('image-preview').removeAttribute?.('src');$('image-original').removeAttribute?.('href');restoreDialogFocus()};

function appendHighlighted(root,value){const text=String(value);if(!messageQuery){root.textContent=text;return}const escaped=messageQuery.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),pattern=new RegExp(escaped,'giu');let cursor=0;for(const match of text.matchAll(pattern)){if(match.index>cursor){const span=document.createElement('span');span.textContent=text.slice(cursor,match.index);root.append(span)}const mark=document.createElement('mark');mark.className='search-match';mark.textContent=match[0];root.append(mark);cursor=match.index+match[0].length}if(cursor<text.length){const span=document.createElement('span');span.textContent=text.slice(cursor);root.append(span)}}

// Keep unchanged messages and media mounted; touch only changed conversation nodes.
function reconcileNodes(root,nodes){const keep=new Set(nodes);for(const node of Array.from(root.childNodes))if(!keep.has(node))root.removeChild(node);let cursor=root.firstChild;for(const node of nodes){if(node===cursor)cursor=cursor.nextSibling;else root.insertBefore(node,cursor||null)}}

function readPinState(){const data=readObject(PINS_KEY);return new Set(Object.keys(data).filter(key=>/^(groups|dms):\d{1,30}$/.test(key)&&data[key]===true).slice(0,200))}
function renderPinButton(){const on=current&&pinnedChats.has(mode+':'+(current.parent_id||current.id));$('pin-chat').disabled=!current;$('pin-chat').setAttribute('aria-pressed',String(!!on));$('pin-chat').setAttribute('aria-label',on?'Unpin conversation':'Pin conversation');$('pin-label').textContent=on?'Pinned':'Pin';$('pin-chat').title=on?'Unpin from your Dock conversation list':'Keep this conversation at the top of your Dock list'}
$('pin-chat').onclick=()=>{if(!current)return;const key=mode+':'+(current.parent_id||current.id),on=pinnedChats.has(key);if(!on&&pinnedChats.size>=200){status('Unpin a conversation before adding another (200 maximum).');return}if(on)pinnedChats.delete(key);else pinnedChats.add(key);try{localStorage.setItem(PINS_KEY,JSON.stringify(Object.fromEntries([...pinnedChats].map(key=>[key,true]))))}catch{status('Pin changed for this session; browser storage is unavailable.')}renderGroups()};

function canGroupMessages(previous,message){if(!previous||previous.system||message.system||previous.sender_type==='system'||message.sender_type==='system'||previous.deleted_at||message.deleted_at)return false;const a=String(previous.user_id||previous.sender_id||''),b=String(message.user_id||message.sender_id||''),gap=Number(message.created_at)-Number(previous.created_at);return !!a&&a===b&&previous.name===message.name&&previous.sender_type===message.sender_type&&Number.isFinite(gap)&&gap>=0&&gap<60&&messageDay(previous.created_at)===messageDay(message.created_at)}

function openConversation(group){if(busy)return;if(current?.id===group.id){$('chat-app').dataset.panel='conversation';window.DockGroupMeNotifications?.chatChanged();window.DockGroupMeTyping?.chatChanged();markRead();return}saveDraft();pendingAudio=null;pendingPhoto=null;$('attachment-status').textContent='';captureUnread(group);current=group;window.DockGroupMeTopics?.chatChanged();$('chat-app').dataset.panel='conversation';window.DockGroupMeNotifications?.chatChanged();clearReply();$('send-status').textContent='';source=crypto.randomUUID();lastText='';generation++;messages=[];deferredRender=false;$('messages').replaceChildren();$('text').value='';updateComposeAccess();setConversationTitle(group.parent_group||group);$('refresh').disabled=false;$('text').disabled=false;$('send').disabled=false;restoreDraft();window.DockGroupMeMentions?.reset();window.DockGroupMeTyping?.chatChanged();$('find-messages').disabled=false;$('chat-empty').hidden=true;clearMessageSearch();resetNewMessages();renderGroups();loadMessages()}

function updateComposeAccess(){const readOnly=mode==='dms'||current?.can_post===false;$('compose').hidden=readOnly;$('dm-note').hidden=!readOnly;$('dm-note').textContent=mode==='dms'?'DMs are read-only. GroupMe does not allow sending direct messages through its Developer API.':'Only group owners and admins can post in this announcement topic.'}

document.addEventListener('pointerdown',event=>{for(const row of Array.from($('messages').querySelectorAll?.('.message[data-actions=open]')||[]))if(!row.contains(event.target)){row.dataset.actions='closed';row.querySelector('.message-more')?.setAttribute('aria-expanded','false')}});

function positionMessageTools(row,actions){if(!window.matchMedia?.('(hover:none), (pointer:coarse)').matches||!actions.getBoundingClientRect)return;const bounds=row.getBoundingClientRect(),area=$('messages').getBoundingClientRect(),height=actions.getBoundingClientRect().height;actions.style.top=(bounds.top-area.top>=height+4?-height-4:Math.max(48,Math.min(bounds.height+4,area.bottom-bounds.top-height-4)))+'px'}

// Keep an opening snapshot even after viewing the latest messages clears the badge.
function captureUnread(group){const count=unreadCount(group);unreadStart=count>0?{id:String(group.id),count,afterId:readState[mode+':'+group.id]?.lastId||null,endId:String(group.messages?.last_message_id||''),target:null}:null;$('catch-up').hidden=true}
function resolveUnread(){if(!unreadStart||unreadStart.id!==current?.id)return null;const sorted=messages.filter(m=>!deletedMessages.has(current?.id+':'+m.id)).sort((a,b)=>a.created_at-b.created_at);if(unreadStart.target&&sorted.some(m=>String(m.id)===unreadStart.target))return unreadStart.target;const previous=unreadStart.afterId?sorted.findIndex(m=>String(m.id)===unreadStart.afterId):-1,end=sorted.findIndex(m=>String(m.id)===unreadStart.endId),index=previous>=0?previous+1:end>=unreadStart.count-1?end-unreadStart.count+1:-1;if(index<0||index>=sorted.length)return null;unreadStart.target=String(sorted[index].id);return unreadStart.target}
function updateCatchUp(target=resolveUnread()){const button=$('catch-up');button.hidden=!unreadStart||unreadStart.id!==current?.id||!!messageQuery||!messages.length;button.textContent=target?'Jump to first unread':$('older').hidden?'Jump to earliest available':'Load earlier unread';button.title='Return to messages that arrived since your last visit in Dock';button.disabled=!!unreadStart?.loading}
$('catch-up').onclick=async()=>{if(!unreadStart||reading||busy)return;const snapshot=unreadStart;snapshot.loading=true;updateCatchUp();try{if(!resolveUnread()&&!$('older').hidden){const loaded=await loadMessages(true);if(!loaded||snapshot!==unreadStart)return}if(snapshot!==unreadStart)return;const id=resolveUnread();if(!id&&!$('older').hidden)return;const root=$('messages'),target=id?Array.from(root.children).find(node=>node.id==='first-unread-marker'):Array.from(root.children).find(node=>node.dataset.messageId);if(target){root.scrollTop+=(target.getBoundingClientRect().top-root.getBoundingClientRect().top)-12;followingLatest=nearLatest();savedReadingPosition=followingLatest?null:captureReadingPosition();target.focus({preventScroll:true})}}finally{snapshot.loading=false;updateCatchUp()}};
